content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-007

=== 用户原始指令 (query.txt) ===
整个倒计时的,还剩15分钟能点进游戏,能看今天天气,快超时了提醒我

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个倒计时的,还剩15分钟能点进游戏,能看今天天气,快超时了提醒我",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "卡片顶部显示的防沉迷提醒状态。",
        "sampleValue": "快超时"
      }
    },
    "asset": {
      "primaryIcon": {
        "type": "string",
        "description": "防沉迷计时图标资源路径。",
        "sampleValue": "resources/base/media/icon_timing.png"
      },
      "actionIcon": {
        "type": "string",
        "description": "天气入口图标资源路径。",
        "sampleValue": "resources/base/media/cloudy.png"
      }
    },
    "usage": {
      "remainingText": {
        "type": "string",
        "description": "距离可以进入游戏的剩余时间展示文本。",
        "sampleValue": "15分"
      },
      "usedMinutes": {
        "type": "number",
        "description": "当前倒计时对应的已等待分钟数，用于进度条展示。",
        "sampleValue": 45
      },
      "limitMinutes": {
        "type": "number",
        "description": "倒计时总分钟数，用作进度条总量。",
        "sampleValue": 60
      },
      "progressColor": {
        "type": "string",
        "description": "快超时状态下进度条使用的提醒色。",
        "sampleValue": "#ffe84026"
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "当前天气查询的区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "condition": {
            "type": "string",
            "description": "今日当前天气现象。",
            "sampleValue": "多云"
          },
          "temperatureText": {
            "type": "string",
            "description": "今日当前温度展示文本。",
            "sampleValue": "29°C"
          }
        }
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "底部天气入口的短动作文案。",
        "sampleValue": "看天气"
      }
    },
    "state": {
      "loading": {
        "type": "boolean",
        "description": "天气数据加载状态。",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "防沉迷计时图标，适合表示应用时长、倒计时和防沉迷提醒。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合表示今日天气入口和多云天气状态。"
    }
  ]
}

